pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address sender, uint32 dt, uint256 startBalance) public {
        vm.assume(sender != address(0));
        dt = uint32(bound(dt, 1, 1000000));
        uint256 sendAmt = 10 ether;
        vm.deal(sender, sendAmt + 1 ether);

        uint256 before = c.pastBlockTime();

        uint256 base = block.timestamp;
        vm.warp(base + dt);

        vm.prank(sender);
        (bool ok, ) = address(c).call{value: sendAmt}("");
        assertTrue(ok);

        assertTrue(c.pastBlockTime() == block.timestamp);
    }
}
